bool CTCWeapon_Getters::IsUsableBy(const CThing& thing) const
{
    if (thing.ThingTypeFlags & 8) {
        if (thing.ThingClass == 1 || ((CTCWeapon_Getters*)this)->GetGameSubsystem()->IsSuppressed())
            return true;
